import{_ as r,o as s,c,a5 as e}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"线程池：工作线程、注入与饥饿","description":"本页回答三个问题：线程池如何调度 Task，线程何时注入何时回收，饥饿如何发生和避免。异步模型见Task 与 async/await。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"csharp/03-csharp-concurrency/chapter-11-thread-pool.md","filePath":"csharp/03-csharp-concurrency/chapter-11-thread-pool.md"}'),t={name:"csharp/03-csharp-concurrency/chapter-11-thread-pool.md"};function h(i,a,p,n,l,d){return s(),c("div",null,[...a[0]||(a[0]=[e(`<h1 id="线程池-工作线程、注入与饥饿" tabindex="-1" data-src-line="2" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">线程池：工作线程、注入与饥饿 <a class="header-anchor" href="#线程池-工作线程、注入与饥饿" aria-label="Permalink to &quot;线程池：工作线程、注入与饥饿&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">本页回答三个问题：线程池如何调度 <code>Task</code>，线程何时注入何时回收，饥饿如何发生和避免。异步模型见<a href="./chapter-02-task-async-await.html">Task 与 async/await</a>。</p><h2 id="_1-线程池是什么" tabindex="-1" data-src-line="6" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">1. 线程池是什么 <a class="header-anchor" href="#_1-线程池是什么" aria-label="Permalink to &quot;1. 线程池是什么&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">线程池维护一组可复用的工作线程，<code>Task.Run</code>、<code>async</code> 恢复、<code>Parallel</code> 等都运行在它上面：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Task.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DoWork</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 排队到线程池</span></span></code></pre></div><p data-src-line="14" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">线程池避免频繁创建销毁线程：线程是昂贵资源（栈空间、调度成本），复用它们能显著提升吞吐。线程池动态调整线程数，按需注入、空闲时回收。</p><h2 id="_2-工作线程与注入" tabindex="-1" data-src-line="16" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">2. 工作线程与注入 <a class="header-anchor" href="#_2-工作线程与注入" aria-label="Permalink to &quot;2. 工作线程与注入&quot;">​</a></h2><p data-src-line="18" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">线程池有两个关键指标：</p><ul data-src-line="20" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><li data-src-line="20" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><strong>工作线程数</strong>：当前存在的线程。</li><li data-src-line="21" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><strong>队列长度</strong>：排队等待执行的任务数。</li></ul><p data-src-line="23" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">当任务排队而线程都被占用时，线程池会<strong>注入新线程</strong>来消化队列。但注入不是瞬间完成的：它用「爬坡」策略，每秒钟注入有限数量的线程，避免突发流量下无节制创建线程。</p><p data-src-line="25" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">这个「爬坡」意味着：突发大量任务时，队列会先堆积，线程数逐步上升。这是正常的自适应行为，不是故障。</p><h2 id="_3-线程池饥饿" tabindex="-1" data-src-line="27" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">3. 线程池饥饿 <a class="header-anchor" href="#_3-线程池饥饿" aria-label="Permalink to &quot;3. 线程池饥饿&quot;">​</a></h2><p data-src-line="29" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">饥饿（starvation）是线程池最常见的严重问题：<strong>线程都被阻塞占住，新任务排队等不到线程</strong>。</p><p data-src-line="31" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">典型根因是在线程池线程上<strong>同步阻塞</strong>等待异步操作：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 反例：线程池线程上 .Result/.Wait 同步阻塞</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Task.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> FetchAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().Result; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 阻塞工作线程</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p data-src-line="41" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">工作线程被 <code>.Result</code> 阻塞，异步操作完成后又要线程池线程来恢复，但线程都被占住，形成「等线程 → 无线程」的死循环。证据是队列长度持续增长、线程数不涨或已到上限、请求大量超时。</p><p data-src-line="43" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><strong>修复</strong>：消除同步阻塞，一路 <code>async/await</code>（见<a href="./chapter-02-task-async-await.html">Task 与 async/await</a>）。真正的 I/O 用异步等待，不让线程阻塞在 I/O 上。</p><h2 id="_4-调优-setminthreads" tabindex="-1" data-src-line="45" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">4. 调优：SetMinThreads <a class="header-anchor" href="#_4-调优-setminthreads" aria-label="Permalink to &quot;4. 调优：SetMinThreads&quot;">​</a></h2><p data-src-line="47" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><code>ThreadPool.SetMinThreads</code> 设置线程池的最小线程数，影响启动时的线程数和注入的初始值：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ThreadPool.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetMinThreads</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(workerThreads, completionPortThreads);</span></span></code></pre></div><p data-src-line="53" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">它不能「解决」饥饿——饥饿的根因是同步阻塞，不是线程数不够。盲目调大 <code>MinThreads</code> 只是延迟暴露问题，还增加内存占用。正确做法是先修同步阻塞，再根据压测数据决定是否调整。</p><p data-src-line="55" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><code>SetMaxThreads</code> 设上限，但除非确知后果，否则不要随意调，避免限制线程池的正常注入。</p><h2 id="_5-线程池与-async-await" tabindex="-1" data-src-line="57" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">5. 线程池与 async/await <a class="header-anchor" href="#_5-线程池与-async-await" aria-label="Permalink to &quot;5. 线程池与 async/await&quot;">​</a></h2><p data-src-line="59" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><code>async/await</code> 正是为解决「线程阻塞在 I/O 上」而设计的（见<a href="./chapter-01-why-async.html">为什么需要异步</a>）：</p><ul data-src-line="61" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><li data-src-line="61" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">同步 I/O：线程阻塞等待，占住线程。</li><li data-src-line="62" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">异步 I/O：<code>await</code> 让出线程，I/O 完成后再恢复，线程可服务其他任务。</li></ul><p data-src-line="64" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">因此异步模型下，线程池用少量线程就能服务大量并发 I/O 请求。反过来，在 <code>async</code> 方法里做 CPU 密集的阻塞计算，仍会占住线程——CPU 密集任务应 <code>Task.Run</code> 到线程池隔离，而不是阻塞当前上下文线程。</p><h2 id="_6-后续阅读" tabindex="-1" data-src-line="66" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">6. 后续阅读 <a class="header-anchor" href="#_6-后续阅读" aria-label="Permalink to &quot;6. 后续阅读&quot;">​</a></h2><ul data-src-line="68" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><li data-src-line="68" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><a href="./chapter-02-task-async-await.html">Task 与 async/await</a>解释线程池上的异步恢复。</li><li data-src-line="69" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><a href="./chapter-01-why-async.html">为什么需要异步</a>解释 I/O 与线程池的关系。</li><li data-src-line="70" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><a href="./../07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a>解释饥饿的定位。</li><li data-src-line="71" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><a href="./chapter-05-parallel-linq.html">并行与 LINQ</a>解释 CPU 密集任务的并行。</li></ul><blockquote data-src-line="73" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md"><p data-src-line="73" data-src-file="csharp/03-csharp-concurrency/chapter-11-thread-pool.md">本页的技术边界按 .NET 10 / C# 14 核对；线程池的注入与爬坡策略随运行时版本演进。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/standard/threading/the-managed-thread-pool" target="_blank" rel="noreferrer">线程池</a>。</p></blockquote>`,29)])])}const u=r(t,[["render",h]]);export{k as __pageData,u as default};
